from __future__ import annotations

from pathlib import Path
from typing import Any, Callable

ProgressCb = Callable[[dict[str, Any]], None]


def stub_transcribe(
    *,
    media_path: str,
    language: str = "auto",
    on_progress: ProgressCb | None = None,
) -> list[dict[str, Any]]:
    name = Path(media_path).name or "audio"
    if on_progress:
        on_progress({"stage": "vad", "percent": 10, "detail": "桩 · 语音检测"})
        on_progress({"stage": "transcribe", "percent": 60, "detail": "桩 · 转写"})
    lang = language if language and language != "auto" else "ja"
    sample = {
        "ja": "これはテスト字幕です。",
        "en": "This is a stub subtitle.",
        "zh": "这是测试字幕。",
    }.get(lang, "Stub subtitle line.")
    return [
        {"start": 0.0, "end": 2.5, "text": f"[{name}] {sample}"},
        {"start": 2.5, "end": 5.0, "text": sample},
    ]
